package ru.folio.notes;

import java.awt.*;
import java.awt.geom.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.*;
import javax.imageio.ImageIO;

/** Independent drawing fixtures: noisy, rotated, reversed, off-centre and with small closure gaps. */
public final class ExtendedShapeTests {
    static int assertions,failures,cases;static Random random=new Random(1600);
    static void check(boolean yes,String label){assertions++;if(!yes){failures++;if(failures<=24)System.out.println("FAIL "+label);}}
    static final class Fixture {final String name,kind;final ArrayList<Ink.Pt> points;Fixture(String name,String kind,ArrayList<Ink.Pt> points){this.name=name;this.kind=kind;this.points=points;}}
    static Ink.Pt p(float x,float y){return new Ink.Pt(x,y,1,0,0);}
    static ArrayList<Ink.Pt> polygon(float[][] v){ArrayList<Ink.Pt> p=new ArrayList<>();for(int i=0;i<v.length;i++){float[] a=v[i],b=v[(i+1)%v.length];for(int j=0;j<28;j++){float t=j/28f;p.add(p(a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t));}}p.add(p.get(0));return p;}
    static ArrayList<Ink.Pt> oval(float rx,float ry){ArrayList<Ink.Pt> p=new ArrayList<>();for(int i=0;i<=180;i++){double a=i*Math.PI*2/180;p.add(p(rx*(float)Math.cos(a),ry*(float)Math.sin(a)));}return p;}
    static ArrayList<Ink.Pt> regular(int n){float[][] v=new float[n][2];for(int i=0;i<n;i++){double a=-Math.PI/2+i*Math.PI*2/n;v[i][0]=120*(float)Math.cos(a);v[i][1]=120*(float)Math.sin(a);}return polygon(v);}
    static ArrayList<Ink.Pt> star(int rays,boolean crossed){float[][] v=new float[crossed?rays:rays*2][2];for(int i=0;i<v.length;i++){double a=-Math.PI/2+i*Math.PI*2/v.length;float r=!crossed&&i%2==1?58:125;v[i][0]=r*(float)Math.cos(a);v[i][1]=r*(float)Math.sin(a);}if(crossed){float[][] order=new float[rays][2];for(int i=0;i<rays;i++)order[i]=v[i*2%rays];return polygon(order);}return polygon(v);}
    static void cubic(ArrayList<Ink.Pt> out,float ax,float ay,float bx,float by,float cx,float cy){Ink.Pt start=out.get(out.size()-1);for(int i=1;i<=36;i++){float t=i/36f,u=1-t;out.add(p(u*u*u*start.x+3*u*u*t*ax+3*u*t*t*bx+t*t*t*cx,u*u*u*start.y+3*u*u*t*ay+3*u*t*t*by+t*t*t*cy));}}
    static ArrayList<Ink.Pt> heart(){ArrayList<Ink.Pt> p=new ArrayList<>();p.add(p(0,110));cubic(p,-40,65,-155,-15,-100,-85);cubic(p,-65,-130,-5,-95,0,-45);cubic(p,5,-95,65,-130,100,-85);cubic(p,155,-15,40,65,0,110);return p;}
    static ArrayList<Ink.Pt> cloud(){Area cloud=new Area(new Ellipse2D.Float(-130,-15,85,85));cloud.add(new Area(new Ellipse2D.Float(-100,-65,100,115)));cloud.add(new Area(new Ellipse2D.Float(-35,-105,125,155)));cloud.add(new Area(new Ellipse2D.Float(45,-50,100,115)));cloud.add(new Area(new Rectangle2D.Float(-85,0,185,55)));ArrayList<Ink.Pt> p=new ArrayList<>(),current=new ArrayList<>();PathIterator iterator=cloud.getPathIterator(null,.5);double[] coords=new double[6];while(!iterator.isDone()){int type=iterator.currentSegment(coords);if(type==PathIterator.SEG_MOVETO){if(Math.abs(ShapeRecognizer.area(current))>Math.abs(ShapeRecognizer.area(p)))p=current;current=new ArrayList<>();}if(type==PathIterator.SEG_MOVETO||type==PathIterator.SEG_LINETO)current.add(p((float)coords[0],(float)coords[1]));iterator.next();}if(Math.abs(ShapeRecognizer.area(current))>Math.abs(ShapeRecognizer.area(p)))p=current;p.add(p.get(0));return p;}
    static ArrayList<Fixture> fixtures(){ArrayList<Fixture> f=new ArrayList<>();f.add(new Fixture("Прямоугольник","rectangle",polygon(new float[][]{{-125,-75},{125,-75},{125,75},{-125,75}})));f.add(new Fixture("Квадрат","square",polygon(new float[][]{{-100,-100},{100,-100},{100,100},{-100,100}})));f.add(new Fixture("Окружность","circle",oval(110,110)));f.add(new Fixture("Овал","ellipse",oval(150,70)));f.add(new Fixture("Треугольник","triangle",polygon(new float[][]{{0,-120},{120,90},{-95,90}})));f.add(new Fixture("Прямой треугольник","triangle",polygon(new float[][]{{-100,-100},{100,100},{-100,100}})));f.add(new Fixture("Трапеция","trapezoid",polygon(new float[][]{{-65,-80},{65,-80},{125,80},{-125,80}})));f.add(new Fixture("Косая трапеция","trapezoid",polygon(new float[][]{{-100,-80},{60,-80},{125,80},{-125,80}})));f.add(new Fixture("Параллелограмм","parallelogram",polygon(new float[][]{{-125,-75},{65,-75},{125,75},{-65,75}})));f.add(new Fixture("Ромб","rhombus",polygon(new float[][]{{-125,0},{0,-75},{125,0},{0,75}})));for(int n:new int[]{5,6,7,8,10,12})f.add(new Fixture(n+" углов","polygon",regular(n)));f.add(new Fixture("Вогнутый контур","polygon",polygon(new float[][]{{-100,-90},{110,-90},{110,-10},{-20,-10},{-20,100},{-100,100}})));f.add(new Fixture("Сердце","heart",heart()));f.add(new Fixture("Облако","cloud",cloud()));for(int n:new int[]{4,5,6,8})f.add(new Fixture(n+" лучей","star",star(n,false)));f.add(new Fixture("Пентаграмма","star",star(5,true)));return f;}
    static Ink.Stroke draw(Fixture fixture,int variation){ArrayList<Ink.Pt> samples=ShapeRecognizer.resample(fixture.points,181);samples.remove(samples.size()-1);int offset=variation*17%samples.size(),count=samples.size()-(variation%3==2?4:0);float angle=variation*.41f,noise=variation%2==0?3:8,scale=variation%4==3?.5f:1,c=(float)Math.cos(angle),sn=(float)Math.sin(angle);Ink.Stroke s=new Ink.Stroke();s.width=4;s.color=0xff7971be;for(int i=0;i<count;i++){int j=(offset+(variation%2==0?i:-i)+samples.size()*2)%samples.size();Ink.Pt p=samples.get(j);float x=p.x+(random.nextFloat()-.5f)*noise,y=p.y+(random.nextFloat()-.5f)*noise;s.points.add(new Ink.Pt((300+x*c-y*sn)*scale,(260+x*sn+y*c)*scale,.6f,.3f,.7f));}if(variation%3!=2)s.points.add(s.points.get(0));return s;}
    static void matrix(){long began=System.nanoTime();for(Fixture f:fixtures())for(int variation=0;variation<12;variation++){Ink.Stroke s=draw(f,variation);ShapeRecognizer.Result r=ShapeRecognizer.recognize(s,1);cases++;check(r!=null&&r.kind.equals(f.kind),f.name+" variant "+variation+" => "+(r==null?"none":r.kind));if(r==null)continue;check(r.stroke.action.equals(s.action)&&r.stroke.color==s.color&&r.stroke.width==s.width,"style/action retained");Ink.Pt a=r.stroke.points.get(0),z=r.stroke.points.get(r.stroke.points.size()-1);check(Ink.dist(a.x,a.y,z.x,z.y)<.01,"closed target");for(float t:new float[]{0,.3f,.8f,1})for(Ink.Pt p:r.frame(t).points)check(Float.isFinite(p.x)&&Float.isFinite(p.y),"finite morph");}System.out.println("Checked "+cases+" transformed drawing fixtures in "+Math.round((System.nanoTime()-began)/1000000)+" ms on desktop (not device latency).");}
    static void constraints(){for(Fixture f:fixtures()){Ink.Stroke original=draw(f,0);int count=original.points.size();Ink.Pt start=original.points.get(0);ShapeRecognizer.Result r=ShapeRecognizer.recognize(original,1);check(original.points.size()==count&&original.points.get(0)==start,"recognition does not mutate source");ArrayList<Ink.Pt> hull=ShapeRecognizer.hull(r.stroke.points);ShapeRecognizer.simplify(hull,1);if(f.kind.equals("rectangle")||f.kind.equals("square")){check(hull.size()==4,"rectangle keeps exact corners");for(int i=0;i<4;i++){Ink.Pt a=hull.get(i),b=hull.get((i+1)%4),c=hull.get((i+2)%4);float dot=(a.x-b.x)*(c.x-b.x)+(a.y-b.y)*(c.y-b.y);check(Math.abs(dot)/(Ink.dist(a.x,a.y,b.x,b.y)*Ink.dist(c.x,c.y,b.x,b.y))<.002,"rectangle angles are exactly right");}}if(f.kind.equals("trapezoid")||f.kind.equals("parallelogram")||f.kind.equals("rhombus")){check(hull.size()==4,"quadrilateral retains four vertices");float a=PolygonFitter.parallel(hull.get(0),hull.get(1),hull.get(3),hull.get(2)),b=PolygonFitter.parallel(hull.get(1),hull.get(2),hull.get(0),hull.get(3));check(Math.min(a,b)<.002,"trapezoid has parallel bases");if(!f.kind.equals("trapezoid"))check(Math.max(a,b)<.002,"parallelogram has two parallel pairs");if(f.kind.equals("rhombus")){float length=PolygonFitter.distance(hull.get(0),hull.get(1));for(int i=0;i<4;i++)check(Math.abs(PolygonFitter.distance(hull.get(i),hull.get((i+1)%4))-length)/length<.025,"near-rhombus preserves measured sides without forced equality");}}if(f.kind.equals("heart")||f.kind.equals("star")||f.kind.equals("cloud")||f.kind.equals("trapezoid")){Ink.Stroke far=original.translated(-500000,800000);ShapeRecognizer.Result distant=ShapeRecognizer.recognize(far,1);check(distant!=null&&distant.kind.equals(f.kind),"classification remains stable on distant infinite canvas");original.tool="marker";ShapeRecognizer.Result marker=ShapeRecognizer.recognize(original,1);check(marker!=null&&marker.stroke.tool.equals("marker"),"complex shapes keep flat marker");if(marker!=null)for(Ink.Pt p:marker.stroke.points)check(Math.abs(p.angle-.7f)<.001,"complex marker shape keeps barrel angle");}}System.out.println("PASS exact corner/parallel constraints and preservation of measured near-rhombus sides, immutable source, distant canvas and flat marker preservation");}
    static void negative(){for(Fixture f:fixtures()){ArrayList<Ink.Pt> p=ShapeRecognizer.resample(f.points,181);Ink.Stroke open=new Ink.Stroke();for(int i=0;i<95;i++)open.points.add(p.get(i));check(ShapeRecognizer.recognize(open,1)==null,"open half contour stays freehand: "+f.name);}Ink.Stroke loop=new Ink.Stroke();ArrayList<Ink.Pt> circle=oval(100,100);loop.points.addAll(circle);loop.points.addAll(circle);check(ShapeRecognizer.recognize(loop,1)==null,"repeated circle remains freehand");}
    static void plot(Graphics2D g,Ink.Stroke s,int color){g.setColor(new Color(color));g.setStroke(new BasicStroke(2.4f,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));Path2D path=new Path2D.Float();if(s.points.isEmpty())return;path.moveTo(s.points.get(0).x,s.points.get(0).y);for(Ink.Pt p:s.points)path.lineTo(p.x,p.y);g.draw(path);}
    static void visual(File output)throws Exception{ArrayList<Fixture> fixtures=fixtures();BufferedImage image=new BufferedImage(1200,1600,BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);g.setColor(new Color(0xf7f4ed));g.fillRect(0,0,1200,1600);g.setColor(new Color(0x31384b));g.setFont(new Font("SansSerif",Font.BOLD,24));g.drawString("Folio · распознавание фигур",30,38);for(int i=0;i<fixtures.size();i++){Fixture f=fixtures.get(i);Ink.Stroke source=draw(f,0);ShapeRecognizer.Result r=ShapeRecognizer.recognize(source,1);int x=i%4*300,y=i/4*215+70;Graphics2D c=(Graphics2D)g.create();c.translate(x+150,y+105);c.scale(.62,.62);c.translate(-300,-260);plot(c,source,0xc3b9c7);if(r!=null)plot(c,r.stroke,0x7770bd);c.dispose();g.setColor(r!=null&&r.kind.equals(f.kind)?new Color(0x535d75):Color.RED);g.setFont(new Font("SansSerif",Font.PLAIN,14));g.drawString(f.name,x+16,y+16);}g.setColor(new Color(0x777f8f));g.setFont(new Font("SansSerif",Font.PLAIN,12));g.drawString("Модель производственного распознавания, не снимок Android.",30,1580);g.dispose();ImageIO.write(image,"png",output);}
    public static void main(String[] args)throws Exception{matrix();constraints();negative();visual(new File(args[0]));System.out.println((failures==0?"PASS":"FAIL")+": "+assertions+" extended recognition assertions; "+failures+" failures");if(failures>0)throw new AssertionError("Recognition fixture failures: "+failures);}
}
